<div class="stack"><div class="hero-actions"><div><h1>Gestione negozi</h1><p class="muted">CRUD negozi e presenza frontend.</p></div><a class="btn" href="<?php echo e(url('/admin/stores/create')); ?>">Nuovo negozio</a></div><div class="table-wrap"><table class="table"><thead><tr><th>Negozio</th><th>Descrizione</th><th>Offerte</th><th>Azioni</th></tr></thead><tbody><?php foreach ($items as $store): ?><tr><td><?php echo e($store['name']); ?></td><td><small><?php echo e($store['description']); ?></small></td><td><?php echo e((string) $store['offers_count']); ?></td><td><div class="table-actions"><a class="btn btn-secondary" href="<?php echo e(url('/admin/stores/' . $store['id'] . '/edit')); ?>">Modifica</a><form action="<?php echo e(url('/admin/stores/' . $store['id'] . '/delete')); ?>" method="post"><?php echo csrf_field(); ?><button class="btn btn-danger" type="submit">Elimina</button></form></div></td></tr><?php endforeach; ?></tbody></table></div></div>
